<?php use yii\widgets\ActiveForm; $this->title = '编辑项目'; ?><div class="page-heading compact"><span class="eyebrow">STUDIO CONTENT</span><h1>编辑项目</h1><p>保存草稿，或发布到公开作品集。</p></div><section class="panel editor-panel"><?php $activeForm = ActiveForm::begin(['enableClientScript'=>false,'enableClientValidation'=>false]); ?><?= $activeForm->errorSummary($model) ?><?= $activeForm->field($model,'title')->input('text')->label('项目名称') ?><?= $activeForm->field($model,'summary')->input('text')->label('一句话简介') ?><?= $activeForm->field($model,'description')->textarea(['rows'=>7])->label('详细介绍') ?><?= $activeForm->field($model,'status')->dropDownList(['planning'=>'构思中','active'=>'进行中','completed'=>'已完成'])->label('项目状态') ?><?= $activeForm->field($model,'published')->checkbox()->label('公开展示') ?><?= $activeForm->field($model,'progress')->input('number')->label('完成进度（0–100）') ?><?= $activeForm->field($model,'started_on')->input('date')->label('开始日期') ?><?php if (Yii::$app->user->identity->isAdmin()): ?><?= $activeForm->field($model,'member_ids')->checkboxList(\yii\helpers\ArrayHelper::map($members,'id','name'))->label('参与成员') ?><?php else: ?><p class="form-note">项目成员由管理员分配；新建项目会自动关联到你的成员档案。</p><?php endif ?><div class="button-row"><?= Html::submitButton('保存更改 ✓',['class'=>'button']) ?><a class="text-link" href="/admin/">返回工作台</a></div><?php ActiveForm::end(); ?></section>
